import { createHash } from "node:crypto";
import { chmodSync, mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { expect, it } from "vitest";
import * as recorder from "../../tooling/speckit/bin/record-visual-runtime.ts";

const pnpmIdentity = (recorder as { pnpmIdentity?: (path: string) => {
  readonly launcherDigest: string;
  readonly executableDigest: string;
} }).pnpmIdentity;

// The shell header generated by the pinned pnpm cmd-shim.
const header = [
  "#!/bin/sh",
  "# Resolve $0 through symlinks so basedir is the shim's real directory.",
  "# Cap hops at the kernel's ELOOP limit so a cycle cannot hang the shim.",
  "link=\"$0\"",
  "hops=0",
  "while [ -L \"$link\" ] && [ \"$hops\" -lt 40 ]; do",
  "  hops=$((hops+1))",
  "  target=$(readlink \"$link\")",
  "  case \"$target\" in",
  "    /*) link=\"$target\" ;;",
  "    *)  link=\"$(dirname \"$link\")/$target\" ;;",
  "  esac",
  "done",
  "basedir=$(dirname \"$(echo \"$link\" | sed -e 's,\\\\,/,g')\")",
  "basedir_win=\"$basedir\"",
  "exe=\"\"",
  "msys=\"\"",
  "",
  "case `uname -a` in",
  "  *CYGWIN*|*MINGW*|*MSYS*)",
  "    if command -v cygpath > /dev/null 2>&1; then",
  "      basedir_win=`cygpath -w \"$basedir\"`",
  "    fi",
  "    exe=\".exe\"",
  "    msys=\"true\"",
  "  ;;",
  "  *WSL2*)",
  "    if command -v wslpath > /dev/null 2>&1; then",
  "      basedir_win=\"$(wslpath -w \"$basedir\" 2> /dev/null)\"",
  "      if [ $? -ne 0 ] || [ -z \"$basedir_win\" ]; then",
  "        basedir_win=\"$basedir\"",
  "      else",
  "        exe=\".exe\"",
  "      fi",
  "    fi",
  "  ;;",
  "esac",
  "",
  "",
].join("\n");

function digest(bytes: Buffer | string): string {
  return `sha256:${createHash("sha256").update(bytes).digest("hex")}`;
}

function binary(): Buffer {
  const bytes = Buffer.alloc(64);
  bytes.set([0x7f, 0x45, 0x4c, 0x46, 2, 1, 1]);
  bytes.writeUInt16LE(3, 16);
  bytes.writeUInt16LE(62, 18);
  bytes.writeUInt32LE(1, 20);
  return bytes;
}

function shim(root: string, install: string, bytes: Buffer) {
  const relative = `global/v11/${install}/node_modules/pnpm/pnpm`;
  const executable = join(root, relative);
  const launcher = join(root, "pnpm");
  const source = `${header}exec "$basedir/${relative}"  "$@"\nexit $?\n# cmd-shim-target=${executable}\n`;
  mkdirSync(dirname(executable), { recursive: true });
  writeFileSync(executable, bytes, { mode: 0o700 });
  writeFileSync(launcher, source, { mode: 0o700 });
  return { launcher, executable, source };
}

it("retains raw launcher hashes and matches native pnpm bytes across installation paths", () => {
  const root = mkdtempSync(join(tmpdir(), "ocelle-pnpm-identity-"));
  try {
    const bytes = binary();
    const first = shim(join(root, "runner-a"), "first-install", bytes);
    const second = shim(join(root, "runner-b"), "second-install", bytes);
    expect(pnpmIdentity?.(first.launcher)).toMatchObject({
      launcherDigest: digest(first.source),
      executableDigest: digest(bytes),
    });
    expect(pnpmIdentity?.(second.launcher)).toMatchObject({
      launcherDigest: digest(second.source),
      executableDigest: digest(bytes),
    });
    expect(digest(first.source)).not.toBe(digest(second.source));
    const changed = Buffer.from(bytes);
    changed[63] = 1;
    writeFileSync(second.executable, changed);
    expect(pnpmIdentity?.(second.launcher)).toMatchObject({
      launcherDigest: digest(second.source),
      executableDigest: digest(changed),
    });
    expect(digest(changed)).not.toBe(digest(bytes));
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

it("rejects a launcher whose shell instructions differ from the verified native target", () => {
  const root = mkdtempSync(join(tmpdir(), "ocelle-pnpm-identity-"));
  try {
    const { launcher, source } = shim(root, "install", binary());
    writeFileSync(launcher, source.replace("exec ", "false\nexec "));
    expect(() => pnpmIdentity?.(launcher)).toThrow(/launcher/);
    writeFileSync(launcher, source.replace("cmd-shim-target=", "cmd-shim-target=/different"));
    expect(() => pnpmIdentity?.(launcher)).toThrow(/launcher|target/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});

it("rejects a non-executable target or a target that is not native linux/amd64", () => {
  const root = mkdtempSync(join(tmpdir(), "ocelle-pnpm-identity-"));
  try {
    const { launcher, executable } = shim(root, "install", binary());
    chmodSync(executable, 0o600);
    expect(() => pnpmIdentity?.(launcher)).toThrow(/executable/);
    chmodSync(executable, 0o700);
    const arm = binary();
    arm.writeUInt16LE(183, 18);
    writeFileSync(executable, arm);
    expect(() => pnpmIdentity?.(launcher)).toThrow(/linux\/amd64|native/);
  } finally {
    rmSync(root, { recursive: true, force: true });
  }
});
